import type { AgentDefinition, Options } from "@anthropic-ai/claude-agent-sdk";

export const reader: AgentDefinition = {
  description: "Finds where code lives. Use it to locate the files and tests a task is about.",
  prompt: "You read and search. Return file:line pointers, most relevant first. Never edit anything.",
  tools: ["Read", "Grep", "Glob"],
  model: "claude-haiku-5-5",
  effort: "medium",
};

export const withHelpers: Options = {
  permissionMode: "dontAsk",
  allowedTools: ["Read", "Grep", "Glob", "Agent"],
  agents: { reader },
};

import { z } from "zod";

const Item = z.object({ path: z.string(), lines: z.string(), why: z.string() });
export const ScopeVerdict = z.object({
  verdict: z.enum(["pass", "veto"]),
  unrelated: z.array(Item),
  weakened_tests: z.array(Item),
  note: z.string(),
});
export type ScopeVerdict = z.infer<typeof ScopeVerdict>;
export const scopeSchema = z.toJSONSchema(ScopeVerdict, { target: "draft-7" });

import { query } from "@anthropic-ai/claude-agent-sdk";
import { ScopeVerdict, scopeSchema } from "./verdict.js";

const SCOPE_PROMPT = `You review a diff for scope, like a careful reviewer from another team.
You get the ticket and the diff, nothing else. Veto changes the ticket does not need and tests made weaker.
Cite the file and lines for every item. When you are unsure, pass and say why in the note.`;

export const scopeJudge = async (ticket: string, diff: string): Promise<ScopeVerdict> => {
  for await (const msg of query({
    prompt: `Ticket:\n${ticket}\n\nDiff:\n${diff}`,
    options: {
      model: "claude-sonnet-5-5",
      effort: "medium",
      tools: [],
      settingSources: [],
      systemPrompt: SCOPE_PROMPT,
      outputFormat: { type: "json_schema", schema: scopeSchema },
    },
  })) {
    if (msg.type === "result" && msg.subtype === "success" && !msg.is_error && msg.structured_output) {
      return ScopeVerdict.parse(msg.structured_output);
    }
  }
  throw new Error("the scope judge returned no verdict");
};

