import { z } from "zod";

export const Readiness = z.object({
  verdict: z.enum(["ready", "ask", "hand_back"]),
  reason: z.string(),
  questions: z.array(z.string()).max(5),
});
export const readinessSchema = z.toJSONSchema(Readiness, { target: "draft-7" });

// test/readiness.test.ts
import assert from "node:assert/strict";
import { test } from "node:test";
import { Readiness, readinessSchema } from "../src/readiness.js";

test("the schema is draft-07, the version the SDK validates with", () => {
  assert.equal(readinessSchema.$schema, "http://json-schema.org/draft-07/schema#");
});

test("a recorded ask with two questions parses", () => {
  const v = Readiness.parse({ verdict: "ask", reason: "Which page?", questions: ["Which page?", "Desktop only?"] });
  assert.equal(v.questions.length, 2);
});

test("six questions are refused", () => {
  const six = Array.from({ length: 6 }, (_, i) => `question ${i}`);
  assert.equal(Readiness.safeParse({ verdict: "ask", reason: "vague", questions: six }).success, false);
});
